const resultados = $input.first().json;
const dados = resultados.data;
if (!dados || !Array.isArray(dados) || dados.length === 0) {
  return [{ json: { erro: 'Nenhum chamado encontrado', total: 0 } }];
}
const todosLimpos = dados.map(c => ({
  id: c['2'] || c.id,
  titulo: c['1'] || c.name || '',
  status: c['12'] || c.status,
  descricao: (c['21'] || c.content || '').replace(/<[^>]*>/g, '').trim(),
  localizacao: c['83'] || c.locations_id || '',
  data_abertura: c['15'] || c.date || '',
  solicitante: c['4'] || c.users_id_recipient || '',
  email_solicitante: c['22'] || ''
}));
const chamadosNovos = todosLimpos.filter(c => c.status === 1 || c.status === 'Novo' || c.status === 'New');
if (chamadosNovos.length === 0) {
  return [{ json: { erro: 'Nenhum chamado NOVO para triar', total_abertos: todosLimpos.length } }];
}
return chamadosNovos.map(novo => ({
  json: {
    chamado_atual: novo,
    historico_abertos: todosLimpos.filter(c => c.id !== novo.id)
  }
}));

return $input.all().map(item => {
  try {
    let dados = item.json;
    if (dados?.content?.parts?.[0]?.text) {
      dados = JSON.parse(dados.content.parts[0].text);
    }
    if (dados?.message?.content) {
      try { dados = JSON.parse(dados.message.content); } catch(e) {}
    }
    if (dados.chamado && dados.duplicidade) {
      return { json: dados };
    }
    if (dados.eh_duplicado !== undefined || dados.potencial_duplicata !== undefined) {
      return { json: {
        chamado: dados.chamado || { id: 'desconhecido' },
        duplicidade: {
          eh_duplicado: dados.eh_duplicado || dados.potencial_duplicata || false,
          chamado_referencia_id: dados.chamado_referencia_id || null,
          caracteristicas_match: dados.caracteristicas_match || [],
          justificativa_para_fiscal: dados.justificativa_para_fiscal || 'Sem justificativa'
        }
      }};
    }
    return { json: dados };
  } catch (error) {
    return { json: {
      chamado: { id: 'erro_parse' },
      duplicidade: { eh_duplicado: false, chamado_referencia_id: null, caracteristicas_match: [], justificativa_para_fiscal: 'Erro ao processar resposta da IA: ' + error.message },
      _erro: true
    }};
  }
});

const item = $input.first().json;
const chamado = item.chamado;
const dup = item.duplicidade;
return [{ json: {
  ...item,
  _formulario_titulo: 'Alerta de Duplicidade - Chamado #' + chamado.id,
  _formulario_mensagem: 'A IA identificou o chamado #' + chamado.id + ' ("' + chamado.titulo + '") como possivel duplicata do chamado #' + dup.chamado_referencia_id + '. Motivo: ' + dup.justificativa_para_fiscal + '. Caracteristicas em comum: ' + (dup.caracteristicas_match || []).join(', '),
  _chamado_id: chamado.id,
  _chamado_ref_id: dup.chamado_referencia_id
}}];

const item = $input.first().json;
let chamado = item.chamado;
if (!chamado && item._chamado_id) { chamado = { id: item._chamado_id }; }
return [{ json: { chamado: chamado || item, origem: item.acao === 'SEGUE_PARA_CLASSIFICACAO' ? 'fiscal_rejeitou_duplicidade' : 'nao_duplicado' } }];

